package toolexposure

import (
	_ "embed"
	"encoding/json"
	"fmt"
)

// policies.gen.json is generated by
// packages/cli/tools/generate_tool_exposure_bundle.py from the real,
// authored contract files under packages/cli/contracts/policies/*.json.
// This embed is the ONLY place those files are read into Go; nothing in
// this package (or any package that imports it) hand-lists a policy or an
// operation ID. Mirrors packages/cli/internal/contractbundle/bundle.go's
// //go:embed bundle.gen.json convention exactly, for the same reason: Go's
// embed directive cannot reach outside its own package directory.
//
//go:embed policies.gen.json
var embeddedPoliciesBytes []byte

type policyBundle struct {
	Policies []PolicyDocument `json:"policies"`
}

// LoadPolicies returns every authored ToolExposurePolicy, keyed by the
// operationId it governs. It performs no filtering and no eligibility
// judgment -- that is PolicyEvaluator's job, applied by the caller against
// this map plus a CommandDescriptor bundle.
func LoadPolicies() (map[string]PolicyDocument, error) {
	if len(embeddedPoliciesBytes) == 0 {
		return nil, fmt.Errorf("embedded tool exposure policy bundle is empty")
	}
	var bundle policyBundle
	if err := json.Unmarshal(embeddedPoliciesBytes, &bundle); err != nil {
		return nil, fmt.Errorf("failed to unmarshal embedded tool exposure policy bundle: %w", err)
	}
	if len(bundle.Policies) == 0 {
		return nil, fmt.Errorf("embedded tool exposure policy bundle contains no policies")
	}
	byOperationID := make(map[string]PolicyDocument, len(bundle.Policies))
	for _, p := range bundle.Policies {
		if p.OperationID == "" {
			return nil, fmt.Errorf("embedded tool exposure policy bundle contains a policy with an empty operationId")
		}
		if _, exists := byOperationID[p.OperationID]; exists {
			return nil, fmt.Errorf("embedded tool exposure policy bundle contains duplicate operationId %q", p.OperationID)
		}
		byOperationID[p.OperationID] = p
	}
	return byOperationID, nil
}
